package com.portfolio.agent.answer.synthesis.codec;
import org.junit.jupiter.api.Test; import static org.assertj.core.api.Assertions.*;
class CrossDomainDraftCodecTest { @Test void rejectsUnknownFields(){assertThatThrownBy(()->new CrossDomainDraftCodec().decode("{\"schemaVersion\":\"cross-domain-expression-v1\",\"sectionKind\":\"RELATION\",\"text\":\"x\",\"relationAlias\":\"r1\",\"statementAliases\":[],\"caveatAliases\":[],\"newRelation\":true}" )).isInstanceOf(CrossDomainDraftException.class);} @Test void decodesOnlyAuthorizedAliases(){CrossDomainDraftCodec.Draft d=new CrossDomainDraftCodec().decode("{\"schemaVersion\":\"cross-domain-expression-v1\",\"sectionKind\":\"RELATION\",\"text\":\"safe\",\"relationAlias\":\"r1\",\"statementAliases\":[\"g1\",\"p1\"],\"caveatAliases\":[]}");assertThat(d.getStatementAliases()).containsExactly("g1","p1");} }
